using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Algebra;

internal sealed class JeudyRouleuxGlobalPermutationLieDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Algebra/JeudyRouleuxGlobalPermutationLie.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/LieTheory/jeudyrouleux2024exchange");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The spin-1 three-particle exchange Hamiltonian is outside the Lie algebra generated by global permutations of the spin labels.",
        H("Jeudy–Rouleux global label permutations"), Blocks(
            Node("L", "The generated Lie algebra", LFormula(),
                "Section 3.1, p. 6: “At least in case of (S,N) = (1/2,N) and (S,N) = (1,3) it is easy to see that the Q(ij) span a Lie algebra L of operators on the total space ℋ and that the Cayley table for [Q(α), Q(β)] is identical to this of [Q̃(α), Q̃(β)].” Definition 4, p. 6: “We call Q-representation the product representation (S(2S+1), ℋ, Q), ℋ = ℂ^{(2S+1)^N} the N-lift of Q̃, defined on transpositions (ij) by Q(ij) = Q̃(ij) ⊗ ⋯ ⊗ Q̃(ij) (N times).” Configurations are functions Fin 3 → Fin 3. The row x, column y entry of the global action is one exactly when x = α ∘ y. LieSubalgebra.lieSpan includes all six permutations α of Fin 3. The bracket on matrices is A * B − B * A. This algebra also contains the Lie algebra generated by the three transpositions alone.",
                DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("schrodingerHamiltonian", "The three-particle Hamiltonian", HamiltonianFormula(),
                "Section 2, equation (7), p. 4: “We can then form the multi-particle (non-linear) Hamiltonian (Schrödinger Hamiltonian) H_S(S,N) = Σ_{⟨i,j⟩} P_S(S_i · S_j).” At (S,N) = (1,3), the three unordered pairs are (0,1), (0,2) and (1,2), each counted once. Section 2 identifies the Exchange Operator P_ij = P_S(S_i · S_j); its row x, column y entry is one exactly when x = y ∘ Equiv.swap i j. The formulas use zero-based particle and label indices.",
                DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("claim", "The expectation in Section 3.1", ClaimFormula(),
                "Section 3.1, p. 7: “Moreover since that the CSCO of the P- and Q-reps are the same in this case (see [Jin], p.70), we expect that Schrödinger Hamiltonian P_S, as well as other Hamiltonians, belongs to L.” Here claim is the membership assertion for the Schrödinger Hamiltonian at (S,N) = (1,3); no assertion about other Hamiltonians is included. The space uses all six label permutations. Section 6's enlarged space L̂ = L₁ + L₁* is outside this statement.",
                DescribeRole.Definition, AssessedProvenance.FromLiterature(Source)),
            Node("result", "The Hamiltonian does not belong", new Formula.Not(Parenthesized(ClaimBody())),
                "Every global permutation preserves equality of the first two particle labels, so its generated Lie algebra commutes with the diagonal projector onto that equality. The Hamiltonian's commutator with the projector has entry one at row (1,0,0), column (0,0,1). Hence the Hamiltonian is outside L. This disproves the membership expectation in Section 3.1. The source's CSCO comparisons and the enlarged space in Section 6 are outside this result.",
                DescribeRole.Theorem, AssessedProvenance.FromRepo(Source),
                new OpenProblemResolutionClaim(ProblemSlugRef.Create("jeudy-rouleux-global-permutation-lie"),
                    ResolutionKind.Refuted)))));

    private static DocumentBlock Node(string name, string title, Formula formula, string prose,
        DescribeRole role, AssessedProvenance provenance,
        OpenProblemResolutionClaim? resolution = null) => Describe.Lean(
            DescribeId.Create("jr-global-" + name.ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name), H(title),
            StatementSource.FromAuthor(Disp(formula)), provenance,
            Blocks(Paragraph(Text(prose))), role, openProblemResolutionClaim: resolution);

    private static Formula Named(string name) => Seq(Operatorname, Grp(F.Id(name)));
    private static Formula Qualified(string owner, string name) => Seq(Named(owner), Dot, Named(name));
    private static Formula Call(string name, params Formula[] args) => new Formula.Apply(Named(name), [.. args]);
    private static Formula App(Formula name, params Formula[] args) => new Formula.Apply(name, [.. args]);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
    private static Formula Eq(Formula left, Formula right) => new Formula.Relation(left, FormulaRelationOperator.Equal, right);
    private static Formula Typed(Formula value, Formula type) => Parenthesized(Seq(value, Sp, Colon, Sp, type));
    private static Formula Complex() => Seq(Mathbb, Grp(F.Id("C")));
    private static Formula Fin3() => Call("Fin", D(3));
    private static Formula ConfigurationType() => new Formula.TypeArrow(Fin3(), Fin3());
    private static Formula MatrixType() => Call("Matrix", Parenthesized(ConfigurationType()), Parenthesized(ConfigurationType()), Complex());
    private static Formula Comp(Formula left, Formula right) => Seq(left, Sp, Circ, Sp, right);
    private static Formula EntryFunction(Formula condition) => Seq(Named("fun"), Sp,
        Typed(F.Id("x"), ConfigurationType()), Sp, Typed(F.Id("y"), ConfigurationType()), Sp, Mapsto, Sp,
        Named("if"), Sp, Parenthesized(condition), Sp, Named("then"), Sp, Typed(D(1), Complex()), Sp, Named("else"), Sp, D(0));

    private static Formula LFormula() => Eq(Typed(Named("L"), Call("LieSubalgebra", Complex(), Parenthesized(MatrixType()))),
        App(Qualified("LieSubalgebra", "lieSpan"), Complex(), Parenthesized(MatrixType()),
            Parenthesized(App(Qualified("Set", "range"), Parenthesized(Seq(Named("fun"), Sp,
                Typed(Alpha, App(Qualified("Equiv", "Perm"), Fin3())), Sp, Mapsto, Sp,
                Typed(App(Qualified("Matrix", "of"), Parenthesized(EntryFunction(Eq(F.Id("x"), Comp(Alpha, F.Id("y")))))), MatrixType())))))));
    private static Formula ExchangeEntry(byte i, byte j) => App(Qualified("Matrix", "of"), Parenthesized(EntryFunction(
        Eq(F.Id("x"), Comp(F.Id("y"), Parenthesized(App(Qualified("Equiv", "swap"), D(i), D(j))))))));
    private static Formula HamiltonianFormula() => Eq(Typed(Named("schrodingerHamiltonian"), MatrixType()),
        new Formula.Binary(new Formula.Binary(ExchangeEntry(0, 1), FormulaBinaryOperator.Add,
            ExchangeEntry(0, 2)), FormulaBinaryOperator.Add, ExchangeEntry(1, 2)));
    private static Formula ClaimBody() => Seq(Named("schrodingerHamiltonian"), Sp, InMacro, Sp, Named("L"));
    private static Formula ClaimFormula() => new Formula.Logic(Named("claim"), FormulaLogicOperator.Iff, Parenthesized(ClaimBody()));
}
